const trips = $input.all().map(item => item.json);

const options = trips.map((trip, index) => {

  return {
    label: trip.trip_name,
    value: trip.trip_id,
    description: `${trip.destination} | ${trip.start_date} - ${trip.end_date}`,
    displayOrder: index,
    hidden: false
  };
});

return [
  {
    json: {
      label: "SLT Destination, Date and Season",
      description: "Lista de SLTs disponibles como opciones de dropdown",
      options: options
    }
  }
];

const { Client } = require("@hubspot/api-client");
const hubspotClient = new Client({ accessToken: $vars.hs_token_3 });

const propertyConfig = $input.first().json;

const PropertyUpdate = {
  groupName: "operations_information",
  hidden: false,
  options: propertyConfig.options,
  displayOrder: -1,
  description: propertyConfig.description,
  label: propertyConfig.label,
  type: "enumeration",
  fieldType: "select",
  formField: true,
};

const objectType = "contact";
const propertyName = "slt_destination_date_and_season";

const apiResponse = await hubspotClient.crm.properties.coreApi.update(
  objectType,
  propertyName,
  PropertyUpdate,
);

return [{ json: apiResponse }];

